cd /private/tmp/claude-501/pr86-ci-live/lt/runs/sysspec89/fx; python3 - <<'E'
import json,re
p=json.load(open('eval-log/run-dev-graph-node/import-payload.json'))
rd=open('system-spec/00-requirements-definition.md').read()
secs={}
for chunk in rd.split('\n## ')[1:]:
    h,_,b=chunk.partition('\n'); secs[h.strip()]=b.strip()
a=p['artifacts'][1]
for k,v in a['sections'].items():
    if re.match(r'U\d ',k): print(k, secs.get(k,'MISSING').replace('**','')==v.strip())
keys=[]
for art in p['artifacts']:
    keys.append(art['title']); keys+=list(art['sections'])
    for st,d in art.get('subtype_sections',{}).items(): keys+=list(d)
bad=[k for k in keys if '\n' in k or len(k)>120 or k.lstrip().startswith('#')]
print(len(keys),'bad',bad,max(len(k) for k in keys))
t=json.dumps(p,ensure_ascii=False)
print(re.findall(r'(?i)(api[_-]?key|secret\s*[:=]|password\s*[:=]|token\s*[:=]|BEGIN [A-Z ]*PRIVATE|ghp_|sk-[A-Za-z0-9]{10}|AKIA[0-9A-Z]{12})',t))
for art in p['artifacts']:
    c=sorted([x['confidence'] for x in art['classification']['candidates']],reverse=True); print(art['slug'],c[0],round(c[0]-c[1],2),art['classification']['decision'])
c=json.load(open('plugins/dev-graph/templates/template-contract.json'))
arts=c['artifacts']
for kind in ['specification','architecture']:
    print(kind, json.dumps(arts[kind],ensure_ascii=False)[:1500])
E

